2362: // Collapse a joint group's static meshes into one mesh per material. This keeps
2363: // the rig intact while cutting hundreds of draw calls per knight.
2364: function mergeDirectMeshes(group, skip) {
2365:   const batches = new Map();
2366:   const remove = [];
2367:   for (const child of group.children) {
2368:     if (!child.isMesh || skip.has(child)) continue;
2369:     child.updateMatrix();
2370:     const key = child.material.uuid;
2371:     let batch = batches.get(key);
2372:     if (!batch) { batch = { mat: child.material, geos: [] }; batches.set(key, batch); }
2373:     const geo = (child.geometry.index ? child.geometry.toNonIndexed() : child.geometry.clone());
2374:     geo.applyMatrix4(child.matrix);
2375:     batch.geos.push(geo);
2376:     remove.push(child);
2377:   }
2378:   if (!remove.length) return;
2379:   for (const child of remove) group.remove(child);
2380:   for (const { mat, geos } of batches.values()) {
2381:     const merged = geos.length > 1 ? mergeGeometries(geos, false) : geos[0];
2382:     if (!merged) {
2383:       for (const geo of geos) { const m = new THREE.Mesh(geo, mat); m.castShadow = true; group.add(m); }
2384:       continue;
2385:     }
2386:     if (geos.length > 1) for (const geo of geos) geo.dispose();
2387:     const mesh = new THREE.Mesh(merged, mat);
2388:     mesh.castShadow = true; group.add(mesh);
2389:   }
2390: }
