3448: // ============ DROP SYSTEM ============
3449: function weightedLootPick(pool) {
3450:   let total = 0;
3451:   for (const d of pool) total += DROP_WEIGHTS[d.id] || 1;
3452:   let r = Math.random() * total;
3453:   for (const d of pool) {
3454:     r -= DROP_WEIGHTS[d.id] || 1;
3455:     if (r <= 0) return d;
3456:   }
3457:   return pool[pool.length - 1];
3458: }
3459: function lootOwned(d) {
3460:   return d.type === 'weapon' ? P.owned.includes(d.id) : P.spoils.includes(d.id);
3461: }
3462: function lootPoolFor(bossId, type) {
3463:   if (type === 'weapon') return SWORD_DROPS;
3464:   const shard = bossId ? bossShardFor(bossId) : null;
3465:   return shard ? [...SPOIL_DROPS, { ...shard, type: 'spoils' }] : SPOIL_DROPS;
3466: }
3467: function rollDrops(bossId = null) {
3468:   const out = [], used = new Set();
3469:   for (let i = 0; i < 3; i++) {
3470:     let type = Math.random() < 0.5 ? 'weapon' : 'spoils';
3471:     let pool = lootPoolFor(bossId, type).filter(d => !used.has(d.id) && !lootOwned(d));
3472:     if (!pool.length) {
3473:       type = type === 'weapon' ? 'spoils' : 'weapon';
3474:       pool = lootPoolFor(bossId, type).filter(d => !used.has(d.id) && !lootOwned(d));
3475:     }
3476:     if (!pool.length) pool = lootPoolFor(bossId, type).filter(d => !used.has(d.id));
3477:     if (!pool.length) pool = lootPoolFor(bossId, type);
3478:     const pick = weightedLootPick(pool);
3479:     used.add(pick.id);
3480:     out.push({ ...pick });
3481:   }
3482:   return out;
3483: }
3484: function bossDropsFor(id) { return rollDrops(id); }
