3423: // cloth simulation: cache rest positions, then let capes breathe and billow
3424: function cacheCloth(mesh, amp = 1) {
3425:   if (!mesh) return;
3426:   const p = mesh.geometry.attributes.position;
3427:   let y0 = Infinity, y1 = -Infinity;
3428:   for (let i = 0; i < p.count; i++) { const y = p.getY(i); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
3429:   mesh.userData.cloth = { base: Float32Array.from(p.array), y0, y1, amp };
3430: }
3431: for (const K of [playerK, bossK]) { cacheCloth(K.parts.cape, 0.9); cacheCloth(K.parts.cape2, 1.25); }
3432: for (const panel of witchK.parts.skirtPanels) cacheCloth(panel, 0.5);
3433: function animateCloth(mesh, time, updateNormals = true) {
3434:   const c = mesh.userData.cloth; if (!c) return;
3435:   const p = mesh.geometry.attributes.position, base = c.base;
3436:   const span = Math.max(0.001, c.y1 - c.y0);
3437:   for (let i = 0; i < p.count; i++) {
3438:     const x = base[i * 3], y = base[i * 3 + 1], z = base[i * 3 + 2];
