  scene.add(parts.group);
  skeletons.push(s);
  spawnRing(new THREE.Vector3(x, 0, z), 0xdbe9ff, 2.6);
  spawnSparks(new THREE.Vector3(x, 0.5, z), 18, 0xd8d2c2, 4);
