3449: function cacheCloth(mesh, amp = 1) {
3450:   if (!mesh) return;
3451:   const p = mesh.geometry.attributes.position;
3452:   let y0 = Infinity, y1 = -Infinity;
3453:   for (let i = 0; i < p.count; i++) { const y = p.getY(i); y0 = Math.min(y0, y); y1 = Math.max(y1, y); }
3454:   mesh.userData.cloth = { base: Float32Array.from(p.array), y0, y1, amp };
3455: }
