node --input-type=module <<'EOF'
import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage();
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://127.0.0.1:3000', { waitUntil: 'load' });
await page.waitForFunction(() => window.__game && document.querySelector('#loading')?.style.display === 'none', { timeout: 45000 });
const result = await page.evaluate(() => {
  const g = window.__game;
  g.enterBossArena('duo');
  g.G.mode = 'play';
  document.querySelector('#title-screen').style.display = 'none';
  document.querySelector('#hud').classList.remove('hidden');
  g.beginDuo();
  const [vesper, morrow] = g.duoTwins;
  vesper.pos.set(g.P.pos.x - 3, 0, g.P.pos.z - 8);
  morrow.pos.set(g.P.pos.x + 4, 0, g.P.pos.z - 6);
  for (const twin of g.duoTwins) twin.k.group.position.copy(twin.pos);
  g.setCreatorMode?.(false);
  g.toggleLock();
  const first = g.lockTargetInfo()?.key;
  g.toggleLock();
  const second = g.lockTargetInfo()?.key;
  const selectedBeforeMove = g.lockTargetInfo()?.key;
  const [selectedTwin] = selectedBeforeMove.split(':');
  if (selectedTwin === 'duo') {
    const twin = g.duoTwins[Number(selectedBeforeMove.split(':')[1])];
    twin.pos.x += 20;
    twin.k.group.position.copy(twin.pos);
  }
  const selectedAfterMove = g.lockTargetInfo()?.key;
  return { first, second, selectedBeforeMove, selectedAfterMove, locked: g.G.locked };
});
console.log(JSON.stringify({ result, errors }, null, 2));
await browser.close();
